import itertools

def is_realizable(degrees):
    degrees = sorted(degrees, reverse=True)
    if sum(degrees) % 2 != 0:
        return False
    n = len(degrees)
    for k in range(1, n + 1):
        left = sum(degrees[:k])
        right = k * (k - 1) + sum(min(k, d) for d in degrees[k:])
        if left > right:
            return False
    return True

def calculate_max_S(degrees):
    degrees = sorted(degrees, reverse=True)
    S = 0
    for k in range(1, 10):
        V_k = [d for d in degrees if d > k]
        m_k = len(V_k)
        if m_k == 0:
            continue
        sum_V_k = sum(V_k)
        sum_not_V_k = sum(d for d in degrees if d <= k)

        E_k = min(sum_V_k, sum_not_V_k, m_k * (11 - m_k))
        if E_k % 2 != sum_V_k % 2:
            E_k -= 1
        S += E_k
    return S

max_s = 0
# Let's try all possible degree sequences? No, too many.
# Let's try some combinations of degrees.
# The number of vertices is 11.
# Let's try to have some vertices of degree 10, some of degree 1, etc.
for d1 in range(1, 11):
    for d2 in range(d1, 11):
        # Let's try a sequence with some d1s and some d2s.
        for n1 in range(1, 11):
            for n2 in range(0, 11 - n1):
                if n1 + n2 == 11:
                    seq = [d1] * n1 + [d2] * n2
                    if is_realizable(seq):
                        max_s = max(max_s, calculate_max_S(seq))
print(f"Max S from two-degree sequences: {max_s}")

# Let's try sequences with three degrees.
for d1 in range(1, 11):
    for d2 in range(d1, 11):
        for d3 in range(d2, 11):
            for n1 in range(1, 11):
                for n2 in range(0, 11 - n1):
                    for n3 in range(0, 11 - n1 - n2):
                        if n1 + n2 + n3 == 11:
                            seq = [d1] * n1 + [d2] * n2 + [d3] * n3
                            if is_realizable(seq):
                                max_s = max(max_s, calculate_max_S(seq))
print(f"Max S from three-degree sequences: {max_s}")

