def generate_graphical_sequences(n, max_d):
    # Use the property that a sequence is graphical if it's even and 
    # satisfies the Erdős-Gallai theorem.
    # We can generate all non-increasing sequences and then filter.
    def generate(current_seq):
        if len(current_seq) == n:
            if is_graphical(current_seq):
                yield list(current_seq)
            return

        prev_d = current_seq[-1] if current_seq else max_d
        for d in range(prev_d, -1, -1):
            yield from generate(current_seq + [d])

