def is_graphical(degrees):
    degrees = sorted(degrees, reverse=True)
    n = len(degrees)
    sum_d = sum(degrees)
    if sum_d % 2 != 0:
        return False
    for k in range(1, n + 1):
        left_sum = sum(degrees[:k])
        right_sum = k * (k - 1)
        for i in range(k, n):
            right_sum += min(k, degrees[i])
        if left_sum > right_sum:
            return False
    return True

def max_s_for_degrees(degrees):
    n = len(degrees)
    d = sorted(degrees, reverse=True)
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            edges.append((d[i] - d[j], i, j))
    edges.sort(key=lambda x: x[0], reverse=True)

    current_degrees = list(d)
    total_s = 0
    for weight, i, j in edges:
        if current_degrees[i] > 0 and current_degrees[j] > 0:
            current_degrees[i] -= 1
            current_degrees[j] -= 1
            total_s += weight
    return total_s

